import { useMemo, useState } from 'react';
import {
  JxChip,
  JxProgressCircle,
  JxBadge,
  JxPagination,
  JxEmptyState,
  JxButton,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

interface Project {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
}

const STATUS_LABEL: Record<ProjectStatus, string> = {
  active: 'Активен',
  paused: 'На паузе',
  over: 'Превышен',
};

const STATUS_TONE: Record<ProjectStatus, 'success' | 'warning' | 'danger'> = {
  active: 'success',
  paused: 'warning',
  over: 'danger',
};

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Аврора', quota: 42, status: 'active' },
  { id: 'p2', name: 'Бумеранг', quota: 88, status: 'over' },
  { id: 'p3', name: 'Вектор', quota: 15, status: 'paused' },
  { id: 'p4', name: 'Горизонт', quota: 67, status: 'active' },
  { id: 'p5', name: 'Дельта', quota: 100, status: 'over' },
  { id: 'p6', name: 'Единорог', quota: 30, status: 'paused' },
  { id: 'p7', name: 'Жасмин', quota: 54, status: 'active' },
  { id: 'p8', name: 'Зенит', quota: 91, status: 'over' },
  { id: 'p9', name: 'Икра', quota: 12, status: 'paused' },
  { id: 'p10', name: 'Йота', quota: 76, status: 'active' },
  { id: 'p11', name: 'Каскад', quota: 38, status: 'active' },
  { id: 'p12', name: 'Лоцман', quota: 20, status: 'paused' },
];

const STATUS_FILTERS: ProjectStatus[] = ['active', 'paused', 'over'];
const PAGE_SIZE = 5;

export default function ProjectSpendPanel() {
  const [activeStatuses, setActiveStatuses] = useState<ProjectStatus[]>(STATUS_FILTERS);
  const [page, setPage] = useState(1);

  const toggleStatus = (status: ProjectStatus) => {
    setActiveStatuses((prev) =>
      prev.includes(status) ? prev.filter((s) => s !== status) : [...prev, status]
    );
    setPage(1);
  };

  const resetFilters = () => {
    setActiveStatuses(STATUS_FILTERS);
    setPage(1);
  };

  const filtered = useMemo(
    () => PROJECTS.filter((project) => activeStatuses.includes(project.status)),
    [activeStatuses]
  );

  const pageCount = Math.max(1, Math.ceil(filtered.length / PAGE_SIZE));
  const currentPage = Math.min(page, pageCount);
  const visible = filtered.slice((currentPage - 1) * PAGE_SIZE, currentPage * PAGE_SIZE);

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 16,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        padding: 20,
        maxWidth: 640,
      }}
    >
      <div>
        <div
          style={{
            fontFamily: 'var(--jx-font-sans)',
            fontSize: 13,
            color: 'var(--jx-text-2)',
            marginBottom: 8,
          }}
        >
          Статус
        </div>
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8 }}>
          {STATUS_FILTERS.map((status) => (
            <JxChip
              key={status}
              active={activeStatuses.includes(status)}
              removable={activeStatuses.includes(status)}
              onClick={() => toggleStatus(status)}
              onRemove={() => toggleStatus(status)}
            >
              {STATUS_LABEL[status]}
            </JxChip>
          ))}
        </div>
      </div>

      {visible.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="По выбранным фильтрам проектов нет."
          action={
            <JxButton variant="secondary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
            {visible.map((project) => (
              <div
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: 16,
                  padding: '12px 8px',
                  borderBottom: '1px solid var(--jx-rule)',
                }}
              >
                <div
                  style={{
                    flex: 1,
                    fontFamily: 'var(--jx-font-sans)',
                    color: 'var(--jx-text)',
                    fontSize: 14,
                  }}
                >
                  {project.name}
                </div>
                <JxProgressCircle value={project.quota} showValue />
                <JxBadge tone={STATUS_TONE[project.status]} dot>
                  {STATUS_LABEL[project.status]}
                </JxBadge>
              </div>
            ))}
          </div>

          <JxPagination total={pageCount} page={currentPage} onPageChange={setPage} />
        </>
      )}
    </div>
  );
}

